@Test
public void testAndValidateClusteringOutputFiles() throws IOException {
    String partitionPath = "2015/03/16";
    testInsertTwoBatches(true, partitionPath);
    // Trigger clustering
    HoodieWriteConfig.Builder cfgBuilder = getConfigBuilder().withEmbeddedTimelineServerEnabled(false).withAutoCommit(false).withClusteringConfig(HoodieClusteringConfig.newBuilder().withClusteringPlanStrategyClass(JavaSizeBasedClusteringPlanStrategy.class.getName()).withClusteringExecutionStrategyClass(JavaSortAndSizeExecutionStrategy.class.getName()).withInlineClustering(true).withInlineClusteringNumCommits(2).build());
    try (HoodieJavaWriteClient client = getHoodieWriteClient(cfgBuilder.build())) {
        int numRecords = 200;
        String newCommitTime = client.createNewInstantTime();
        List<HoodieRecord> records1 = dataGen.generateInserts(newCommitTime, numRecords);
        client.startCommitWithTime(newCommitTime);
        List<WriteStatus> statuses = client.insert(records1, newCommitTime);
        client.commit(newCommitTime, statuses);
        assertNoWriteErrors(statuses);
        metaClient = HoodieTableMetaClient.reload(metaClient);
        HoodieInstant replaceCommitInstant = metaClient.getActiveTimeline().getCompletedReplaceTimeline().firstInstant().get();
        HoodieReplaceCommitMetadata replaceCommitMetadata = HoodieReplaceCommitMetadata.fromBytes(metaClient.getActiveTimeline().getInstantDetails(replaceCommitInstant).get(), HoodieReplaceCommitMetadata.class);
        List<String> filesFromReplaceCommit = new ArrayList<>();
        replaceCommitMetadata.getPartitionToWriteStats().forEach((k, v) -> v.forEach(entry -> filesFromReplaceCommit.add(entry.getPath())));
        // find all parquet files created as part of clustering. Verify it matches w/ what is found in replace commit metadata.
        FileStatus[] fileStatuses = fs.listStatus(new Path(basePath + "/" + partitionPath));
        List<String> clusteredFiles = Arrays.stream(fileStatuses).filter(entry -> entry.getPath().getName().contains(replaceCommitInstant.getTimestamp())).map(fileStatus -> partitionPath + "/" + fileStatus.getPath().getName()).collect(Collectors.toList());
        assertEquals(clusteredFiles, filesFromReplaceCommit);
    }
}

