public void testWriteClientAndTableServiceClientWithTimelineServer(boolean enableEmbeddedTimelineServer, boolean passInTimelineServer) throws IOException {
    metaClient = HoodieTableMetaClient.reload(metaClient);
    HoodieWriteConfig writeConfig = HoodieWriteConfig.newBuilder().withIndexConfig(HoodieIndexConfig.newBuilder().withIndexType(INMEMORY).build()).withPath(metaClient.getBasePathV2().toString()).withEmbeddedTimelineServerEnabled(enableEmbeddedTimelineServer).build();
