        // for future upserts. so, renaming the file here to some temp name and later renaming it back to same name.
        metaFilePath = Paths.get(HoodieTestUtils.getCompleteInstantPath(metaClient.getFs(), new Path(metadataTableBasePath, METAFOLDER_NAME), metadataCompactionInstant, HoodieTimeline.COMMIT_ACTION).toUri());
