        assertEquals(HoodieTableMetadataUtil.getPartitionLatestFileSlices(metadataReader.getMetadataMetaClient(), Option.empty(), MetadataPartitionType.RECORD_INDEX.getPartitionPath()).size(), 5);
    }
    // remove the MDT partition from dataset to simulate failed bootstrap
