        metaClient = HoodieTableMetaClient.reload(metaClient);
        assertTrue(metaClient.getTableConfig().isMetadataTableAvailable());
        validateMetadata(client);
        // File groups should be created as in the config
        HoodieBackedTableMetadata metadataReader = (HoodieBackedTableMetadata) metadata(client);
        assertEquals(HoodieTableMetadataUtil.getPartitionLatestFileSlices(metadataReader.getMetadataMetaClient(), Option.empty(), MetadataPartitionType.FILES.getPartitionPath()).size(), 1);
        assertEquals(HoodieTableMetadataUtil.getPartitionLatestFileSlices(metadataReader.getMetadataMetaClient(), Option.empty(), MetadataPartitionType.RECORD_INDEX.getPartitionPath()).size(), 3);
    }
}

