@Test
public void testRollbackOfRegularCommitWithPendingReplaceCommitInTimeline() throws Exception {
    HoodieClusteringConfig clusteringConfig = HoodieClusteringConfig.newBuilder().withClusteringMaxNumGroups(10).withClusteringTargetPartitions(0).withInlineClusteringNumCommits(1).withInlineClustering(true).fromProperties(getDisabledRowWriterProperties()).build();
