@Test
public void testClusteringCommitInPresenceOfInflightCommit() throws Exception {
    Properties properties = getDisabledRowWriterProperties();
    properties.setProperty(FILESYSTEM_LOCK_PATH_PROP_KEY, basePath + "/.hoodie/.locks");
    HoodieLockConfig lockConfig = HoodieLockConfig.newBuilder().withLockProvider(FileSystemBasedLockProviderTestClass.class).withConflictResolutionStrategy(new PreferWriterConflictResolutionStrategy()).build();
    HoodieCleanConfig cleanConfig = HoodieCleanConfig.newBuilder().withFailedWritesCleaningPolicy(HoodieFailedWritesCleaningPolicy.LAZY).withAutoClean(false).build();
    HoodieWriteConfig insertWriteConfig = getConfigBuilder().withAutoCommit(false).withCleanConfig(cleanConfig).withLockConfig(lockConfig).withWriteConcurrencyMode(WriteConcurrencyMode.OPTIMISTIC_CONCURRENCY_CONTROL).withProperties(properties).build();
    SparkRDDWriteClient client = getHoodieWriteClient(insertWriteConfig);
    // Create a base commit on a file.
    int numRecords = 200;
    String firstCommit = client.createNewInstantTime();
    String partitionStr = HoodieTestDataGenerator.DEFAULT_FIRST_PARTITION_PATH;
    HoodieTestDataGenerator dataGenerator = new HoodieTestDataGenerator(new String[] { partitionStr });
    writeBatch(client, firstCommit, "000", Option.of(Arrays.asList("000")), "000", numRecords, dataGenerator::generateInserts, SparkRDDWriteClient::insert, true, numRecords, numRecords, 1, true);
    // Do an upsert operation without autocommit.
    String inflightCommit = client.createNewInstantTime();
    writeBatch(client, inflightCommit, firstCommit, Option.of(Arrays.asList("000")), "000", 100, dataGenerator::generateUniqueUpdates, SparkRDDWriteClient::upsert, false, 0, 200, 2, false);
    // Schedule and execute a clustering plan on the same partition. During conflict resolution the commit should fail.
    HoodieClusteringConfig clusteringConfig = HoodieClusteringConfig.newBuilder().withClusteringMaxNumGroups(10).withClusteringTargetPartitions(0).withInlineClusteringNumCommits(1).build();
    HoodiePreCommitValidatorConfig preCommitValidatorConfig = HoodiePreCommitValidatorConfig.newBuilder().withPreCommitValidator(StringUtils.nullToEmpty(SqlQuerySingleResultPreCommitValidator.class.getName())).withPrecommitValidatorSingleResultSqlQueries(COUNT_SQL_QUERY_FOR_VALIDATION + "#200").build();
    HoodieWriteConfig clusteringWriteConfig = getConfigBuilder().withAutoCommit(false).withCleanConfig(cleanConfig).withClusteringConfig(clusteringConfig).withPreCommitValidatorConfig(preCommitValidatorConfig).withLockConfig(lockConfig).withWriteConcurrencyMode(WriteConcurrencyMode.OPTIMISTIC_CONCURRENCY_CONTROL).withProperties(properties).build();
    // create client with new config.
    String clusteringCommitTime = client.createNewInstantTime();
    SparkRDDWriteClient clusteringWriteClient = getHoodieWriteClient(clusteringWriteConfig);
    // Schedule and execute clustering, this should fail since there is a conflict between ingestion inflight commit.
    clusteringWriteClient.scheduleClusteringAtInstant(clusteringCommitTime, Option.empty());
    assertThrows(HoodieClusteringException.class, () -> clusteringWriteClient.cluster(clusteringCommitTime, true));
    // Do a rollback on the replacecommit that is failed
    clusteringWriteClient.rollback(clusteringCommitTime);
    // Verify the timeline
    List<HoodieInstant> instants = metaClient.reloadActiveTimeline().getInstants();
    assertEquals(3, instants.size());
    assertEquals(HoodieActiveTimeline.ROLLBACK_ACTION, instants.get(2).getAction());
    assertEquals(new HoodieInstant(true, HoodieActiveTimeline.COMMIT_ACTION, inflightCommit), instants.get(1));
}

