    // Create and temporarily block a lower timestamp for ingestion.
    String inflightCommit = client.createNewInstantTime();
    JavaRDD<WriteStatus> ingestionResult = writeBatch(client, inflightCommit, firstCommit, Option.of(Arrays.asList("000")), "000", 100, dataGenerator::generateUniqueUpdates, SparkRDDWriteClient::upsert, false, 0, 200, 2, false);
    // Schedule and execute a clustering plan on the same partition. During conflict resolution the commit should fail.
    HoodieClusteringConfig clusteringConfig = HoodieClusteringConfig.newBuilder().withClusteringMaxNumGroups(10).withClusteringTargetPartitions(0).withInlineClusteringNumCommits(1).build();
    // Since it is harder to test corner cases where the ingestion writer is at dedupe step right before the inflight file creation
    // and clustering commit is just about to complete, using the default conflict resolutions strategy only for clustering job
    // To create a successful commit.
    HoodieLockConfig clusteringLockConfig = HoodieLockConfig.newBuilder().withLockProvider(FileSystemBasedLockProviderTestClass.class).withConflictResolutionStrategy(new SimpleConcurrentFileWritesConflictResolutionStrategy()).build();
    HoodiePreCommitValidatorConfig preCommitValidatorConfig = HoodiePreCommitValidatorConfig.newBuilder().withPreCommitValidator(StringUtils.nullToEmpty(SqlQuerySingleResultPreCommitValidator.class.getName())).withPrecommitValidatorSingleResultSqlQueries(COUNT_SQL_QUERY_FOR_VALIDATION + "#200").build();
    HoodieWriteConfig clusteringWriteConfig = getConfigBuilder().withAutoCommit(false).withCleanConfig(cleanConfig).withClusteringConfig(clusteringConfig).withPreCommitValidatorConfig(preCommitValidatorConfig).withLockConfig(clusteringLockConfig).withWriteConcurrencyMode(WriteConcurrencyMode.OPTIMISTIC_CONCURRENCY_CONTROL).withProperties(properties).build();
    // create client with new config.
    SparkRDDWriteClient clusteringWriteClient = getHoodieWriteClient(clusteringWriteConfig);
    String clusteringCommitTime = clusteringWriteClient.createNewInstantTime();
    // Schedule and execute clustering, this complete successfully.
    clusteringWriteClient.scheduleClusteringAtInstant(clusteringCommitTime, Option.empty());
    clusteringWriteClient.cluster(clusteringCommitTime, true);
    // When ingestion writer is committing it should throw an exception.
    assertThrows(HoodieWriteConflictException.class, () -> client.commit(inflightCommit, ingestionResult));
}

