            put(p2, "id22");
            put(p3, "id23");
        }
    };
    Map<String, String> partitionAndFileId3 = new HashMap<String, String>() {

        {
            put(p1, "id31");
            put(p2, "id32");
            put(p3, "id33");
        }
    };
    HoodieWriteConfig config = HoodieWriteConfig.newBuilder().withPath(basePath).withRollbackUsingMarkers(false).withMetadataConfig(HoodieMetadataConfig.newBuilder().// Column Stats Index is disabled, since these tests construct tables which are
    // not valid (empty commit metadata, invalid parquet files)
    withMetadataIndexColumnStats(false).enable(enableMetadataTable).build()).withCleanConfig(HoodieCleanConfig.newBuilder().withFailedWritesCleaningPolicy(HoodieFailedWritesCleaningPolicy.LAZY).build()).withIndexConfig(HoodieIndexConfig.newBuilder().withIndexType(HoodieIndex.IndexType.INMEMORY).build()).build();
    HoodieTableMetadataWriter metadataWriter = enableMetadataTable ? SparkHoodieBackedTableMetadataWriter.create(hadoopConf, config, context) : null;
    HoodieTestTable testTable = enableMetadataTable ? HoodieMetadataTestTable.of(metaClient, metadataWriter, Option.of(context)) : HoodieTestTable.of(metaClient);
    testTable.withPartitionMetaFiles(p1, p2, p3).addCommit(commitTime1).withBaseFilesInPartitions(partitionAndFileId1).getLeft().addCommit(commitTime2).withBaseFilesInPartitions(partitionAndFileId2).getLeft().addInflightCommit(commitTime3).withBaseFilesInPartitions(partitionAndFileId3);
    try (SparkRDDWriteClient client = getHoodieWriteClient(config)) {
