@ParameterizedTest
@MethodSource("providerClassResolutionStrategyAndTableType")
public void testMultiWriterWithAsyncTableServicesWithConflict(HoodieTableType tableType, Class providerClass, ConflictResolutionStrategy resolutionStrategy) throws Exception {
    // create inserts X 1
    if (tableType == HoodieTableType.MERGE_ON_READ) {
        setUpMORTestTable();
    }
    // Use RDD API to perform clustering (TODO: Fix row-writer API)
    Properties properties = new Properties();
    properties.put("hoodie.datasource.write.row.writer.enable", String.valueOf(false));
    // Disabling embedded timeline server, it doesn't work with multiwriter
    HoodieWriteConfig.Builder writeConfigBuilder = getConfigBuilder().withCleanConfig(HoodieCleanConfig.newBuilder().withAutoClean(false).withAsyncClean(true).retainCommits(0).withFailedWritesCleaningPolicy(HoodieFailedWritesCleaningPolicy.LAZY).build()).withCompactionConfig(HoodieCompactionConfig.newBuilder().withInlineCompaction(false).withMaxNumDeltaCommitsBeforeCompaction(2).build()).withEmbeddedTimelineServerEnabled(false).// Timeline-server-based markers are not used for multi-writer tests
    withMarkersType(MarkerType.DIRECT.name()).withFileSystemViewConfig(FileSystemViewStorageConfig.newBuilder().withStorageType(FileSystemViewStorageType.MEMORY).build()).withWriteConcurrencyMode(WriteConcurrencyMode.OPTIMISTIC_CONCURRENCY_CONTROL).withLockConfig(HoodieLockConfig.newBuilder().withLockProvider(providerClass).withConflictResolutionStrategy(resolutionStrategy).build()).withAutoCommit(false).withProperties(lockProperties).withProperties(properties);
    Set<String> validInstants = new HashSet<>();
    // Create the first commit with inserts
    HoodieWriteConfig cfg = writeConfigBuilder.build();
    SparkRDDWriteClient client = getHoodieWriteClient(cfg);
    String firstCommitTime = client.createNewInstantTime();
    createCommitWithInserts(cfg, client, "000", firstCommitTime, 200, true);
    validInstants.add(firstCommitTime);
    // Create 2 commits with upserts
    String secondCommitTime = client.createNewInstantTime();
    createCommitWithUpserts(cfg, client, firstCommitTime, "000", secondCommitTime, 100);
    String thirdCommitTime = client.createNewInstantTime();
    createCommitWithUpserts(cfg, client, secondCommitTime, "000", thirdCommitTime, 100);
    validInstants.add(secondCommitTime);
    validInstants.add(thirdCommitTime);
    // Three clients running actions in parallel
    final int threadCount = 3;
    final CountDownLatch scheduleCountDownLatch = new CountDownLatch(threadCount);
    final ExecutorService executors = Executors.newFixedThreadPool(threadCount);
    // Write config with clustering enabled
    final HoodieWriteConfig cfg2 = writeConfigBuilder.withClusteringConfig(HoodieClusteringConfig.newBuilder().withInlineClustering(true).withInlineClusteringNumCommits(1).build()).build();
    final SparkRDDWriteClient client1 = getHoodieWriteClient(cfg2);
    final SparkRDDWriteClient client2 = getHoodieWriteClient(cfg);
    final SparkRDDWriteClient client3 = getHoodieWriteClient(cfg);
    // Create upserts, schedule cleaning, schedule compaction in parallel
    Future future1 = executors.submit(() -> {
        final String newCommitTime = client1.createNewInstantTime();
        final int numRecords = 100;
        final String commitTimeBetweenPrevAndNew = secondCommitTime;
        // We want the upsert to go through only after the compaction
        // and cleaning schedule completion. So, waiting on latch here.
        latchCountDownAndWait(scheduleCountDownLatch, 30000);
        if (tableType == HoodieTableType.MERGE_ON_READ && !(resolutionStrategy instanceof PreferWriterConflictResolutionStrategy)) {
            // HUDI-6897: Improve SimpleConcurrentFileWritesConflictResolutionStrategy for NB-CC
            // There is no need to throw concurrent modification exception for the simple strategy under NB-CC, because the compactor would finally resolve the conflicts instead.
            // Since the concurrent modifications went in, this upsert has
            // to fail
            assertThrows(HoodieWriteConflictException.class, () -> {
                createCommitWithUpserts(cfg, client1, thirdCommitTime, commitTimeBetweenPrevAndNew, newCommitTime, numRecords);
            });
        } else {
            // We don't have the compaction for COW and so this upsert
            // has to pass
            assertDoesNotThrow(() -> {
                createCommitWithUpserts(cfg, client1, thirdCommitTime, commitTimeBetweenPrevAndNew, newCommitTime, numRecords);
            });
            validInstants.add(newCommitTime);
        }
    });
    Future future2 = executors.submit(() -> {
        if (tableType == HoodieTableType.MERGE_ON_READ) {
            assertDoesNotThrow(() -> {
                String compactionTimeStamp = client2.createNewInstantTime();
                client2.scheduleTableService(compactionTimeStamp, Option.empty(), TableServiceType.COMPACT);
            });
        }
        latchCountDownAndWait(scheduleCountDownLatch, 30000);
    });
    Future future3 = executors.submit(() -> {
        assertDoesNotThrow(() -> {
            latchCountDownAndWait(scheduleCountDownLatch, 30000);
            String cleanCommitTime = client3.createNewInstantTime();
            client3.scheduleTableService(cleanCommitTime, Option.empty(), TableServiceType.CLEAN);
        });
    });
    future1.get();
    future2.get();
    future3.get();
    String pendingCompactionTime = (tableType == HoodieTableType.MERGE_ON_READ) ? metaClient.reloadActiveTimeline().filterPendingCompactionTimeline().firstInstant().get().getTimestamp() : "";
    Option<HoodieInstant> pendingCleanInstantOp = metaClient.reloadActiveTimeline().getCleanerTimeline().filterInflightsAndRequested().firstInstant();
    String pendingCleanTime = pendingCleanInstantOp.isPresent() ? pendingCleanInstantOp.get().getTimestamp() : client.createNewInstantTime();
    CountDownLatch runCountDownLatch = new CountDownLatch(threadCount);
    // Create inserts, run cleaning, run compaction in parallel
    future1 = executors.submit(() -> {
        final String newCommitTime = client1.createNewInstantTime();
        final int numRecords = 100;
        latchCountDownAndWait(runCountDownLatch, 30000);
        assertDoesNotThrow(() -> {
            createCommitWithInserts(cfg, client1, thirdCommitTime, newCommitTime, numRecords, true);
            validInstants.add(newCommitTime);
        });
    });
    future2 = executors.submit(() -> {
        latchCountDownAndWait(runCountDownLatch, 30000);
        if (tableType == HoodieTableType.MERGE_ON_READ) {
            assertDoesNotThrow(() -> {
                HoodieWriteMetadata<JavaRDD<WriteStatus>> compactionMetadata = client2.compact(pendingCompactionTime);
                client2.commitCompaction(pendingCompactionTime, compactionMetadata.getCommitMetadata().get(), Option.empty());
                validInstants.add(pendingCompactionTime);
            });
        }
    });
    future3 = executors.submit(() -> {
        latchCountDownAndWait(runCountDownLatch, 30000);
        assertDoesNotThrow(() -> {
            client3.clean(pendingCleanTime, false);
            validInstants.add(pendingCleanTime);
        });
    });
    future1.get();
    future2.get();
    future3.get();
    validInstants.addAll(metaClient.reloadActiveTimeline().getCompletedReplaceTimeline().filterCompletedInstants().getInstantsAsStream().map(HoodieInstant::getTimestamp).collect(Collectors.toSet()));
    Set<String> completedInstants = metaClient.reloadActiveTimeline().getCommitsTimeline().filterCompletedInstants().getInstantsAsStream().map(HoodieInstant::getTimestamp).collect(Collectors.toSet());
    assertTrue(validInstants.containsAll(completedInstants));
    client.close();
    client1.close();
    client2.close();
    client3.close();
}

