public void testWriteClientAndTableServiceClientWithTimelineServer(boolean enableEmbeddedTimelineServer, boolean passInTimelineServer) throws IOException {
    HoodieTableMetaClient metaClient = getHoodieMetaClient(hadoopConf(), URI.create(basePath()).getPath(), new Properties());
    HoodieWriteConfig writeConfig = getConfigBuilder(true).withPath(metaClient.getBasePathV2().toString()).withEmbeddedTimelineServerEnabled(enableEmbeddedTimelineServer).withFileSystemViewConfig(FileSystemViewStorageConfig.newBuilder().withRemoteServerPort(incrementTimelineServicePortToUse()).build()).build();
    SparkRDDWriteClient writeClient;
    if (passInTimelineServer) {
        EmbeddedTimelineService timelineService = new EmbeddedTimelineService(context(), null, writeConfig);
        timelineService.startServer();
        writeConfig.setViewStorageConfig(timelineService.getRemoteFileSystemViewConfig());
        writeClient = new SparkRDDWriteClient(context(), writeConfig, Option.of(timelineService));
        // Both the write client and the table service client should use the same passed-in
        // timeline server instance.
        assertEquals(timelineService, writeClient.getTimelineServer().get());
        assertEquals(timelineService, writeClient.getTableServiceClient().getTimelineServer().get());
        // Write config should not be changed
        assertEquals(writeConfig, writeClient.getConfig());
        timelineService.stop();
    } else {
        writeClient = new SparkRDDWriteClient(context(), writeConfig);
        // Only one timeline server should be instantiated, and the same timeline server
        // should be used by both the write client and the table service client.
        assertEquals(writeClient.getTimelineServer(), writeClient.getTableServiceClient().getTimelineServer());
        if (!enableEmbeddedTimelineServer) {
            assertFalse(writeClient.getTimelineServer().isPresent());
        }
    }
    writeClient.close();
}

@ParameterizedTest
@MethodSource
void testWriteClientReleaseResourcesShouldOnlyUnpersistRelevantRdds(HoodieTableType tableType, boolean shouldReleaseResource, boolean metadataTableEnable) throws IOException {
    final HoodieTableMetaClient metaClient = getHoodieMetaClient(hadoopConf(), URI.create(basePath()).getPath(), tableType, new Properties());
    final HoodieWriteConfig writeConfig = getConfigBuilder(true).withPath(metaClient.getBasePathV2().toString()).withAutoCommit(false).withReleaseResourceEnabled(shouldReleaseResource).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(metadataTableEnable).build()).build();
    HoodieTestDataGenerator dataGen = new HoodieTestDataGenerator(0xDEED);
    String instant0 = getCommitTimeAtUTC(0);
    List<GenericRecord> extraRecords0 = dataGen.generateGenericRecords(10);
    HoodieJavaRDD<GenericRecord> persistedRdd0 = HoodieJavaRDD.of(jsc().parallelize(extraRecords0, 2));
    persistedRdd0.persist("MEMORY_AND_DISK", context(), HoodieDataCacheKey.of(writeConfig.getBasePath(), instant0));
    String instant1 = getCommitTimeAtUTC(1);
    List<GenericRecord> extraRecords1 = dataGen.generateGenericRecords(10);
    HoodieJavaRDD<GenericRecord> persistedRdd1 = HoodieJavaRDD.of(jsc().parallelize(extraRecords1, 2));
    persistedRdd1.persist("MEMORY_AND_DISK", context(), HoodieDataCacheKey.of(writeConfig.getBasePath(), instant1));
    SparkRDDWriteClient writeClient = getHoodieWriteClient(writeConfig);
    List<HoodieRecord> records = dataGen.generateInserts(instant1, 10);
    JavaRDD<HoodieRecord> writeRecords = jsc().parallelize(records, 2);
    writeClient.startCommitWithTime(instant1);
    List<WriteStatus> writeStatuses = writeClient.insert(writeRecords, instant1).collect();
    assertNoWriteErrors(writeStatuses);
    String metadataTableBasePath = HoodieTableMetadata.getMetadataTableBasePath(writeConfig.getBasePath());
    List<Integer> metadataTableCacheIds0 = context().getCachedDataIds(HoodieDataCacheKey.of(metadataTableBasePath, instant0));
    List<Integer> metadataTableCacheIds1 = context().getCachedDataIds(HoodieDataCacheKey.of(metadataTableBasePath, instant1));
    writeClient.commitStats(instant1, context().parallelize(writeStatuses, 1), writeStatuses.stream().map(WriteStatus::getStat).collect(Collectors.toList()), Option.empty(), metaClient.getCommitActionType());
    writeClient.close();
    if (shouldReleaseResource) {
        assertEquals(Collections.singletonList(persistedRdd0.getId()), context().getCachedDataIds(HoodieDataCacheKey.of(writeConfig.getBasePath(), instant0)), "RDDs cached for " + instant0 + " should be retained.");
        assertEquals(Collections.emptyList(), context().getCachedDataIds(HoodieDataCacheKey.of(writeConfig.getBasePath(), instant1)), "RDDs cached for " + instant1 + " should be cleared.");
        assertTrue(jsc().getPersistentRDDs().containsKey(persistedRdd0.getId()), "RDDs cached for " + instant0 + " should be retained.");
        assertFalse(jsc().getPersistentRDDs().containsKey(persistedRdd1.getId()), "RDDs cached for " + instant1 + " should be cleared.");
        assertFalse(jsc().getPersistentRDDs().containsKey(writeRecords.id()), "RDDs cached for " + instant1 + " should be cleared.");
        if (metadataTableEnable) {
            assertEquals(metadataTableCacheIds0.stream().sorted().collect(Collectors.toList()), context().getCachedDataIds(HoodieDataCacheKey.of(metadataTableBasePath, instant0)).stream().sorted().collect(Collectors.toList()), "RDDs cached for metadataTable " + instant0 + " should be retained.");
            assertEquals(Collections.emptyList(), context().getCachedDataIds(HoodieDataCacheKey.of(metadataTableBasePath, instant1)), "RDDs cached for metadataTable " + instant1 + " should be cleared.");
            metadataTableCacheIds0.forEach(cacheId -> assertTrue(jsc().getPersistentRDDs().containsKey(cacheId), "RDDs cached for metadataTable cacheId " + cacheId + " should be retained."));
            metadataTableCacheIds1.forEach(cacheId -> assertFalse(jsc().getPersistentRDDs().containsKey(cacheId), "RDDs cached for metadataTable cacheId " + cacheId + " should be cleared."));
        }
    } else {
        assertEquals(Collections.singletonList(persistedRdd0.getId()), context().getCachedDataIds(HoodieDataCacheKey.of(writeConfig.getBasePath(), instant0)), "RDDs cached for " + instant0 + " should be retained.");
        assertEquals(3, context().getCachedDataIds(HoodieDataCacheKey.of(writeConfig.getBasePath(), instant1)).size(), "RDDs cached for " + instant1 + " should be retained.");
        assertTrue(jsc().getPersistentRDDs().containsKey(persistedRdd0.getId()), "RDDs cached for " + instant0 + " should be retained.");
        assertTrue(jsc().getPersistentRDDs().containsKey(persistedRdd1.getId()), "RDDs cached for " + instant1 + " should be retained.");
        assertTrue(jsc().getPersistentRDDs().containsKey(writeRecords.id()), "RDDs cached for " + instant1 + " should be retained.");
        if (metadataTableEnable) {
            metadataTableCacheIds0.forEach(cacheId -> assertTrue(jsc().getPersistentRDDs().containsKey(cacheId), "RDDs cached for metadataTable cacheId " + cacheId + " should be retained."));
            metadataTableCacheIds1.forEach(cacheId -> assertTrue(jsc().getPersistentRDDs().containsKey(cacheId), "RDDs cached for metadataTable cacheId " + cacheId + " should be retained."));
        }
    }
}

@Test
public void testSchemaCompatibilityBasic() {
    assertTrue(isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, TRIP_EXAMPLE_SCHEMA, false), "Same schema is compatible");
    String reorderedSchema = TRIP_SCHEMA_PREFIX + EXTRA_TYPE_SCHEMA + TIP_NESTED_SCHEMA + FARE_NESTED_SCHEMA + MAP_TYPE_SCHEMA + TRIP_SCHEMA_SUFFIX;
    assertTrue(isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, reorderedSchema, false), "Reordered fields are compatible");
    assertTrue(isSchemaCompatible(reorderedSchema, TRIP_EXAMPLE_SCHEMA, false), "Reordered fields are compatible");
    String renamedSchema = TRIP_EXAMPLE_SCHEMA.replace("tip_history", "tip_future");
    assertFalse(isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, renamedSchema, false), "Renaming fields is essentially: dropping old field, created a new one");
    assertTrue(isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, renamedSchema, true), "Renaming fields is essentially: dropping old field, created a new one");
    String renamedRecordSchema = TRIP_EXAMPLE_SCHEMA.replace("triprec", "triprec_renamed");
    assertFalse(isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, renamedRecordSchema, false), "Renamed record name is not compatible");
    String swappedFieldSchema = TRIP_SCHEMA_PREFIX + MAP_TYPE_SCHEMA.replace("city_to_state", "fare") + FARE_NESTED_SCHEMA.replace("fare", "city_to_state") + TIP_NESTED_SCHEMA + TRIP_SCHEMA_SUFFIX;
    assertFalse(isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, swappedFieldSchema, false), "Swapped fields are not compatible");
    String typeChangeSchemaDisallowed = TRIP_SCHEMA_PREFIX + MAP_TYPE_SCHEMA + FARE_NESTED_SCHEMA + TIP_NESTED_SCHEMA.replace("string", "boolean") + TRIP_SCHEMA_SUFFIX;
    assertFalse(isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, typeChangeSchemaDisallowed, false), "Incompatible field type change is not allowed");
    // Array of allowed schema field type transitions
    String[][] allowedFieldChanges = { { "string", "bytes" }, { "bytes", "string" }, { "int", "long" }, { "int", "float" }, { "long", "float" }, { "int", "double" }, { "float", "double" }, { "long", "double" } };
    for (String[] fieldChange : allowedFieldChanges) {
        String fromSchema = TRIP_SCHEMA_PREFIX + EXTRA_FIELD_SCHEMA.replace("string", fieldChange[0]) + TRIP_SCHEMA_SUFFIX;
        String toSchema = TRIP_SCHEMA_PREFIX + EXTRA_FIELD_SCHEMA.replace("string", fieldChange[1]) + TRIP_SCHEMA_SUFFIX;
        assertTrue(isSchemaCompatible(fromSchema, toSchema, false), "Compatible field type change is not allowed");
        if (!fieldChange[0].equals("byte") && fieldChange[1].equals("byte")) {
            assertFalse(isSchemaCompatible(toSchema, fromSchema, false), "Incompatible field type change is allowed");
        }
    }
    // Names and aliases should match
    String fromSchema = TRIP_SCHEMA_PREFIX + EXTRA_FIELD_SCHEMA + TRIP_SCHEMA_SUFFIX;
    String toSchema = TRIP_SCHEMA_PREFIX.replace("triprec", "new_triprec") + EXTRA_FIELD_SCHEMA + TRIP_SCHEMA_SUFFIX;
    assertFalse(isSchemaCompatible(fromSchema, toSchema, false), "Field names should match");
    assertFalse(isSchemaCompatible(toSchema, fromSchema, false), "Field names should match");
    assertTrue(isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, TRIP_EXAMPLE_SCHEMA_EVOLVED_COL_ADDED, false), "Added field with default is compatible (Evolved Schema)");
    String multipleAddedFieldSchema = TRIP_SCHEMA_PREFIX + EXTRA_TYPE_SCHEMA + MAP_TYPE_SCHEMA + FARE_NESTED_SCHEMA + TIP_NESTED_SCHEMA + EXTRA_FIELD_SCHEMA + EXTRA_FIELD_SCHEMA.replace("new_field", "new_new_field") + TRIP_SCHEMA_SUFFIX;
    assertTrue(isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, multipleAddedFieldSchema, false), "Multiple added fields with defaults are compatible");
    assertFalse(isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, TRIP_SCHEMA_PREFIX + EXTRA_TYPE_SCHEMA + MAP_TYPE_SCHEMA + FARE_NESTED_SCHEMA + TIP_NESTED_SCHEMA + EXTRA_FIELD_WITHOUT_DEFAULT_SCHEMA + TRIP_SCHEMA_SUFFIX, false), "Added field without default and not nullable is not compatible (Evolved Schema)");
    assertTrue(isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, TRIP_SCHEMA_PREFIX + EXTRA_TYPE_SCHEMA + MAP_TYPE_SCHEMA + FARE_NESTED_SCHEMA + TIP_NESTED_SCHEMA + TRIP_SCHEMA_SUFFIX + EXTRA_FIELD_NULLABLE_SCHEMA, false), "Added nullable field is compatible (Evolved Schema)");
}

@ParameterizedTest
@ValueSource(booleans = { false, true })
public void testMORTable(boolean shouldAllowDroppedColumns) throws Exception {
    tableType = HoodieTableType.MERGE_ON_READ;
    // Create the table
    HoodieTableMetaClient.withPropertyBuilder().fromMetaClient(metaClient).setTableType(HoodieTableType.MERGE_ON_READ).setTimelineLayoutVersion(VERSION_1).initTable(metaClient.getHadoopConf(), metaClient.getBasePath());
    HoodieWriteConfig hoodieWriteConfig = getWriteConfig(TRIP_EXAMPLE_SCHEMA, shouldAllowDroppedColumns);
    SparkRDDWriteClient client = getHoodieWriteClient(hoodieWriteConfig);
    // Initial inserts with TRIP_EXAMPLE_SCHEMA
    int numRecords = 10;
    insertFirstBatch(hoodieWriteConfig, client, "001", initCommitTime, numRecords, SparkRDDWriteClient::insert, false, false, numRecords);
    checkLatestDeltaCommit("001");
    // Compact once so we can incrementally read later
    assertTrue(client.scheduleCompactionAtInstant("002", Option.empty()));
    client.compact("002");
    // Updates with same schema is allowed
    final int numUpdateRecords = 5;
    updateBatch(hoodieWriteConfig, client, "003", "002", Option.empty(), initCommitTime, numUpdateRecords, SparkRDDWriteClient::upsert, false, false, 0, 0, 0);
    checkLatestDeltaCommit("003");
    checkReadRecords("000", numRecords);
    // Delete with same schema is allowed
    final int numDeleteRecords = 2;
    numRecords -= numDeleteRecords;
    deleteBatch(hoodieWriteConfig, client, "004", "003", initCommitTime, numDeleteRecords, false, false, 0, 0);
    checkLatestDeltaCommit("004");
    checkReadRecords("000", numRecords);
    // Insert with evolved schema (column dropped) is allowed
    HoodieWriteConfig hoodieDevolvedWriteConfig = getWriteConfig(TRIP_EXAMPLE_SCHEMA_EVOLVED_COL_DROPPED, shouldAllowDroppedColumns);
    client = getHoodieWriteClient(hoodieDevolvedWriteConfig);
    final List<HoodieRecord> failedRecords = generateInsertsWithSchema("005", numRecords, TRIP_EXAMPLE_SCHEMA_EVOLVED_COL_DROPPED);
    // We cannot use insertBatch directly here because we want to insert records
    // with a evolved schema and insertBatch inserts records using the TRIP_EXAMPLE_SCHEMA.
    try {
        writeBatch(client, "005", "004", Option.empty(), "003", numRecords, (String s, Integer a) -> failedRecords, SparkRDDWriteClient::insert, false, numRecords, 2 * numRecords, 5, false);
        assertTrue(shouldAllowDroppedColumns);
    } catch (HoodieInsertException e) {
        assertFalse(shouldAllowDroppedColumns);
        return;
    }
    // Update with evolved schema (column dropped) might be allowed depending on config set.
    updateBatch(hoodieDevolvedWriteConfig, client, "006", "005", Option.empty(), initCommitTime, numUpdateRecords, SparkRDDWriteClient::upsert, false, false, numUpdateRecords, 2 * numRecords, 0);
    // Insert with an evolved scheme is allowed
    HoodieWriteConfig hoodieEvolvedWriteConfig = getWriteConfig(TRIP_EXAMPLE_SCHEMA_EVOLVED_COL_ADDED, shouldAllowDroppedColumns);
    client = getHoodieWriteClient(hoodieEvolvedWriteConfig);
    // We cannot use insertBatch directly here because we want to insert records
    // with an evolved schema and insertBatch inserts records using the TRIP_EXAMPLE_SCHEMA.
    final List<HoodieRecord> evolvedRecords = generateInsertsWithSchema("007", numRecords, TRIP_EXAMPLE_SCHEMA_EVOLVED_COL_ADDED);
    writeBatch(client, "007", "006", Option.empty(), initCommitTime, numRecords, (String s, Integer a) -> evolvedRecords, SparkRDDWriteClient::insert, false, numRecords, 3 * numRecords, 7, false);
    // new commit
    checkLatestDeltaCommit("007");
    checkReadRecords("000", 3 * numRecords);
    // Updates with evolved schema is allowed
    final List<HoodieRecord> updateRecords = generateUpdatesWithSchema("008", numUpdateRecords, TRIP_EXAMPLE_SCHEMA_EVOLVED_COL_ADDED);
    writeBatch(client, "008", "007", Option.empty(), initCommitTime, numUpdateRecords, (String s, Integer a) -> updateRecords, SparkRDDWriteClient::upsert, false, numRecords, 4 * numRecords, 8, false);
    // new commit
    checkLatestDeltaCommit("008");
    checkReadRecords("000", 4 * numRecords);
    // Now try updating w/ the original schema (should succeed)
    client = getHoodieWriteClient(hoodieWriteConfig);
    try {
        updateBatch(hoodieWriteConfig, client, "009", "008", Option.empty(), initCommitTime, numUpdateRecords, SparkRDDWriteClient::upsert, false, false, numUpdateRecords, 4 * numRecords, 9);
        assertTrue(shouldAllowDroppedColumns);
    } catch (HoodieUpsertException e) {
        assertFalse(shouldAllowDroppedColumns);
    }
}

@ParameterizedTest
@ValueSource(booleans = { false, true })
public void testCopyOnWriteTable(boolean shouldAllowDroppedColumns) throws Exception {
    // Create the table
    HoodieTableMetaClient.withPropertyBuilder().fromMetaClient(metaClient).setTimelineLayoutVersion(VERSION_1).initTable(metaClient.getHadoopConf(), metaClient.getBasePath());
    HoodieWriteConfig hoodieWriteConfig = getWriteConfigBuilder(TRIP_EXAMPLE_SCHEMA).withRollbackUsingMarkers(false).withAllowAutoEvolutionColumnDrop(shouldAllowDroppedColumns).build();
    SparkRDDWriteClient client = getHoodieWriteClient(hoodieWriteConfig);
    // Initial inserts with TRIP_EXAMPLE_SCHEMA
    int numRecords = 10;
    insertFirstBatch(hoodieWriteConfig, client, "001", initCommitTime, numRecords, SparkRDDWriteClient::insert, false, true, numRecords);
    checkReadRecords("000", numRecords);
    // Updates with same schema is allowed
    final int numUpdateRecords = 5;
    updateBatch(hoodieWriteConfig, client, "002", "001", Option.empty(), initCommitTime, numUpdateRecords, SparkRDDWriteClient::upsert, false, true, numUpdateRecords, numRecords, 2);
    checkReadRecords("000", numRecords);
    // Delete with same schema is allowed
    final int numDeleteRecords = 2;
    numRecords -= numDeleteRecords;
    deleteBatch(hoodieWriteConfig, client, "003", "002", initCommitTime, numDeleteRecords, false, true, 0, numRecords);
    checkReadRecords("000", numRecords);
    // Inserting records w/ new evolved schema (w/ tip column dropped)
    HoodieWriteConfig hoodieDevolvedWriteConfig = getWriteConfig(TRIP_EXAMPLE_SCHEMA_EVOLVED_COL_DROPPED, shouldAllowDroppedColumns);
    client = getHoodieWriteClient(hoodieDevolvedWriteConfig);
    final List<HoodieRecord> failedRecords = generateInsertsWithSchema("004", numRecords, TRIP_EXAMPLE_SCHEMA_EVOLVED_COL_DROPPED);
    try {
        writeBatch(client, "004", "003", Option.empty(), "003", numRecords, (String s, Integer a) -> failedRecords, SparkRDDWriteClient::insert, true, numRecords, numRecords * 2, 1, false);
        assertTrue(shouldAllowDroppedColumns);
    } catch (HoodieInsertException e) {
        assertFalse(shouldAllowDroppedColumns);
        return;
    }
    // Updating records w/ new evolved schema
    updateBatch(hoodieDevolvedWriteConfig, client, "005", "004", Option.empty(), initCommitTime, numUpdateRecords, SparkRDDWriteClient::upsert, false, true, numUpdateRecords, 2 * numRecords, 5);
    // Inserting with evolved schema is allowed
    HoodieWriteConfig hoodieEvolvedWriteConfig = getWriteConfig(TRIP_EXAMPLE_SCHEMA_EVOLVED_COL_ADDED, shouldAllowDroppedColumns);
    client = getHoodieWriteClient(hoodieEvolvedWriteConfig);
    final List<HoodieRecord> evolvedRecords = generateInsertsWithSchema("006", numRecords, TRIP_EXAMPLE_SCHEMA_EVOLVED_COL_ADDED);
    // We cannot use insertBatch directly here because we want to insert records
    // with a evolved schema.
    writeBatch(client, "006", "005", Option.empty(), initCommitTime, numRecords, (String s, Integer a) -> evolvedRecords, SparkRDDWriteClient::insert, true, numRecords, 3 * numRecords, 6, false);
    // new commit
    HoodieTimeline curTimeline = metaClient.reloadActiveTimeline().getCommitTimeline().filterCompletedInstants();
    assertTrue(curTimeline.lastInstant().get().getTimestamp().equals("006"));
    checkReadRecords("000", 3 * numRecords);
    // Updating with evolved schema is allowed
    final List<HoodieRecord> updateRecords = generateUpdatesWithSchema("007", numUpdateRecords, TRIP_EXAMPLE_SCHEMA_EVOLVED_COL_ADDED);
    writeBatch(client, "007", "006", Option.empty(), initCommitTime, numUpdateRecords, (String s, Integer a) -> updateRecords, SparkRDDWriteClient::upsert, true, numUpdateRecords, 3 * numRecords, 7, false);
    checkReadRecords("000", 3 * numRecords);
    // Now try updating w/ the original schema (should succeed)
    client = getHoodieWriteClient(hoodieWriteConfig);
    try {
        updateBatch(hoodieWriteConfig, client, "008", "007", Option.empty(), initCommitTime, numUpdateRecords, SparkRDDWriteClient::upsert, false, true, numUpdateRecords, 3 * numRecords, 8);
        assertTrue(shouldAllowDroppedColumns);
    } catch (HoodieUpsertException e) {
        assertFalse(shouldAllowDroppedColumns);
    }
}

