@Test
public void testInterruptExecutor() {
    final List<HoodieRecord> hoodieRecords = dataGen.generateInserts(instantTime, 100);
    HoodieConsumer<HoodieLazyInsertIterable.HoodieInsertValueGenResult<HoodieRecord>, Integer> consumer = new HoodieConsumer<HoodieLazyInsertIterable.HoodieInsertValueGenResult<HoodieRecord>, Integer>() {

        @Override
        public void consume(HoodieLazyInsertIterable.HoodieInsertValueGenResult<HoodieRecord> record) {
            try {
                while (true) {
                    Thread.sleep(1000);
                }
            } catch (InterruptedException ie) {
                return;
            }
        }

        @Override
        public Integer finish() {
            return 0;
        }
    };
    BoundedInMemoryExecutor<HoodieRecord, Tuple2<HoodieRecord, Option<IndexedRecord>>, Integer> executor = new BoundedInMemoryExecutor(writeConfig.getWriteBufferLimitBytes(), hoodieRecords.iterator(), consumer, getTransformerInternal(HoodieTestDataGenerator.AVRO_SCHEMA, writeConfig), getPreExecuteRunnable());
    // Interrupt the current thread (therefore triggering executor to throw as soon as it
    // invokes [[get]] on the [[CompletableFuture]])
    Thread.currentThread().interrupt();
    assertThrows(HoodieException.class, executor::execute);
    // Validate that interrupted flag is reset, after [[InterruptedException]] is thrown
    assertTrue(Thread.interrupted());
    executor.shutdownNow();
    executor.awaitTermination();
}

