        {
            put(120 * MB, partitionPaths[2]);
            put(110 * MB, partitionPaths[2]);
            put(100 * MB, partitionPaths[1]);
            put(90 * MB, partitionPaths[0]);
        }
    });
    DayBasedCompactionStrategy strategy = new DayBasedCompactionStrategy();
    HoodieWriteConfig writeConfig = HoodieWriteConfig.newBuilder().withPath("/tmp").withCompactionConfig(HoodieCompactionConfig.newBuilder().withCompactionStrategy(strategy).withTargetPartitionsPerDayBasedCompaction(1).build()).build();
    List<String> filterPartitions = strategy.filterPartitionPaths(writeConfig, Arrays.asList(partitionPaths));
    assertEquals(1, filterPartitions.size(), "DayBasedCompactionStrategy should have resulted in fewer partitions");
    List<HoodieCompactionOperation> operations = createCompactionOperationsForPartition(writeConfig, sizesMap, keyToPartitionMap, filterPartitions);
    assertEquals(2, operations.size(), "DayBasedCompactionStrategy should generate 2 HoodieCompactionOperation for partition 2017/01/03");
    List<String> operationPartitions = operations.stream().collect(Collectors.groupingBy(HoodieCompactionOperation::getPartitionPath)).entrySet().stream().map(e -> e.getKey()).collect(Collectors.toList());
    assertTrue(operationPartitions.size() == filterPartitions.size(), "DayBasedCompactionStrategy should have resulted same partitions");
    int comparison = strategy.getComparator().compare(operations.get(operations.size() - 1).getPartitionPath(), operations.get(0).getPartitionPath());
    // Either the partition paths are sorted in descending order or they are equal
    assertTrue(comparison >= 0, "DayBasedCompactionStrategy should sort partitions in descending order");
}

