@ParameterizedTest
@ValueSource(booleans = { true, false })
public void testMetadataStatsOnCommit(Boolean rollbackUsingMarkers) throws Exception {
    HoodieWriteConfig cfg = getConfigBuilder(false, rollbackUsingMarkers, IndexType.INMEMORY).withAvroSchemaValidate(false).withAllowAutoEvolutionColumnDrop(true).withAutoCommit(false).build();
    setUp(cfg.getProps());
