@Test
public void testGetObjectSize() {
    EmptyClass emptyClass = new EmptyClass();
    StringClass stringClass = new StringClass();
    PayloadClass payloadClass = new PayloadClass();
    String emptyString = "";
    String string = "hello";
    String[] stringArray = { emptyString, string, " world" };
    String[] anotherStringArray = new String[100];
    List<String> stringList = new ArrayList<>();
    StringBuilder stringBuilder = new StringBuilder(100);
    int maxIntPrimitive = Integer.MAX_VALUE;
    int minIntPrimitive = Integer.MIN_VALUE;
    Integer maxInteger = Integer.MAX_VALUE;
    Integer minInteger = Integer.MIN_VALUE;
    long zeroLong = 0L;
    double zeroDouble = 0.0;
    boolean booleanField = true;
    Object object = new Object();
    String name = "Alice Bob";
    Person person = new Person(name);
    if (getJavaVersion() == 11 || getJavaVersion() == 17) {
        assertEquals(48, getObjectSize(string));
        assertEquals(168, getObjectSize(stringArray));
        assertEquals(144, getObjectSize(stringBuilder));
        assertEquals(72, getObjectSize(DayOfWeek.TUESDAY));
        assertEquals(HoodieAvroUtils.gteqAvro1_9() ? 1256 : 1176, getObjectSize(Schema.create(Schema.Type.STRING)));
        assertEquals(96, getObjectSize(person));
    } else {
        assertEquals(56, getObjectSize(string));
        assertEquals(184, getObjectSize(stringArray));
        assertEquals(240, getObjectSize(stringBuilder));
        assertEquals(80, getObjectSize(DayOfWeek.TUESDAY));
        // Since avro 1.9, Schema use ConcurrentHashMap instead of LinkedHashMap to
        // implement props, which will change the size of the object.
        assertEquals(HoodieAvroUtils.gteqAvro1_9() ? 1320 : 1240, getObjectSize(Schema.create(Schema.Type.STRING)));
        assertEquals(104, getObjectSize(person));
    }
    assertEquals(40, getObjectSize(emptyString));
    assertEquals(416, getObjectSize(anotherStringArray));
    assertEquals(40, getObjectSize(stringList));
    assertEquals(16, getObjectSize(maxIntPrimitive));
    assertEquals(16, getObjectSize(minIntPrimitive));
    assertEquals(16, getObjectSize(maxInteger));
    assertEquals(16, getObjectSize(minInteger));
    assertEquals(24, getObjectSize(zeroLong));
    assertEquals(24, getObjectSize(zeroDouble));
    assertEquals(16, getObjectSize(booleanField));
    assertEquals(16, getObjectSize(object));
    assertEquals(32, getObjectSize(emptyClass));
    assertEquals(40, getObjectSize(stringClass));
    assertEquals(40, getObjectSize(payloadClass));
}

@Test
public void testOrcIteratorReadData() throws Exception {
    final Configuration conf = new Configuration();
    Schema avroSchema = getSchemaFromResource(TestOrcReaderIterator.class, "/simple-test.avsc");
    TypeDescription orcSchema = AvroOrcUtils.createOrcSchema(avroSchema);
    OrcFile.WriterOptions options = OrcFile.writerOptions(conf).setSchema(orcSchema).compress(CompressionKind.ZLIB);
    Writer writer = OrcFile.createWriter(filePath, options);
    VectorizedRowBatch batch = orcSchema.createRowBatch();
    BytesColumnVector nameColumns = (BytesColumnVector) batch.cols[0];
    LongColumnVector numberColumns = (LongColumnVector) batch.cols[1];
    BytesColumnVector colorColumns = (BytesColumnVector) batch.cols[2];
    for (int r = 0; r < 5; ++r) {
        int row = batch.size++;
        byte[] name = getUTF8Bytes("name" + r);
        nameColumns.setVal(row, name);
        byte[] color = getUTF8Bytes("color" + r);
        colorColumns.setVal(row, color);
        numberColumns.vector[row] = r;
    }
    writer.addRowBatch(batch);
    writer.close();
    Reader reader = OrcFile.createReader(filePath, OrcFile.readerOptions(conf));
    RecordReader recordReader = reader.rows(new Reader.Options(conf).schema(orcSchema));
    Iterator<GenericRecord> iterator = new OrcReaderIterator<>(recordReader, avroSchema, orcSchema);
    int recordCount = 0;
    while (iterator.hasNext()) {
        GenericRecord record = iterator.next();
        assertEquals("name" + recordCount, record.get("name").toString());
        assertEquals("color" + recordCount, record.get("favorite_color").toString());
        assertEquals(recordCount, record.get("favorite_number"));
        recordCount++;
    }
    assertEquals(5, recordCount);
}

