@Test
public void testReaderGetRecordIteratorByKeys() throws Exception {
    writeFileWithSimpleSchema();
    HoodieAvroHFileReader hfileReader = (HoodieAvroHFileReader) createReader(new Configuration());
    Schema avroSchema = getSchemaFromResource(TestHoodieReaderWriterBase.class, "/exampleSchema.avsc");
    List<String> keys = Collections.singletonList("key");
    Iterator<IndexedRecord> iterator = hfileReader.getIndexedRecordsByKeysIterator(keys, avroSchema);
    List<GenericRecord> recordsByKeys = toStream(iterator).map(r -> (GenericRecord) r).collect(Collectors.toList());
    List<GenericRecord> allRecords = toStream(hfileReader.getRecordIterator()).map(r -> (GenericRecord) r.getData()).collect(Collectors.toList());
    // no entries should match since this is exact match.
    assertEquals(Collections.emptyList(), recordsByKeys);
    // filter for "key00001, key05, key12, key24, key16, key2, key31, key49, key61, key50". Valid entries should be matched.
    // key00001 should not match.
    // even though key16 exists, its not in the sorted order of keys passed in. So, will not return the matched entry.
    // key2 : we don't have an exact match
    // key61 is greater than max key.
    // again, by the time we reach key50, cursor is at EOF. So no entries will be returned.
    List<GenericRecord> expectedKey1s = allRecords.stream().filter(entry -> ((entry.get("_row_key").toString()).contains("key05") || (entry.get("_row_key").toString()).contains("key12") || (entry.get("_row_key").toString()).contains("key24") || (entry.get("_row_key").toString()).contains("key31") || (entry.get("_row_key").toString()).contains("key49"))).collect(Collectors.toList());
    iterator = hfileReader.getIndexedRecordsByKeysIterator(Arrays.asList("key00001", "key05", "key12", "key24", "key16", "key31", "key49", "key61", "key50"), avroSchema);
    recordsByKeys = StreamSupport.stream(Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), false).map(r -> (GenericRecord) r).collect(Collectors.toList());
    assertEquals(expectedKey1s, recordsByKeys);
}

@Test
public void testReaderGetRecordIteratorByKeyPrefixes() throws Exception {
    writeFileWithSimpleSchema();
    HoodieAvroHFileReader hfileReader = (HoodieAvroHFileReader) createReader(new Configuration());
    Schema avroSchema = getSchemaFromResource(TestHoodieReaderWriterBase.class, "/exampleSchema.avsc");
    List<String> keyPrefixes = Collections.singletonList("key");
    Iterator<IndexedRecord> iterator = hfileReader.getIndexedRecordsByKeyPrefixIterator(keyPrefixes, avroSchema);
    List<GenericRecord> recordsByPrefix = toStream(iterator).map(r -> (GenericRecord) r).collect(Collectors.toList());
    List<GenericRecord> allRecords = toStream(hfileReader.getRecordIterator()).map(r -> (GenericRecord) r.getData()).collect(Collectors.toList());
    assertEquals(allRecords, recordsByPrefix);
    // filter for "key1" : entries from key10 to key19 should be matched
    List<GenericRecord> expectedKey1s = allRecords.stream().filter(entry -> (entry.get("_row_key").toString()).contains("key1")).collect(Collectors.toList());
    iterator = hfileReader.getIndexedRecordsByKeyPrefixIterator(Collections.singletonList("key1"), avroSchema);
    recordsByPrefix = StreamSupport.stream(Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), false).map(r -> (GenericRecord) r).collect(Collectors.toList());
    assertEquals(expectedKey1s, recordsByPrefix);
    // exact match
    List<GenericRecord> expectedKey25 = allRecords.stream().filter(entry -> (entry.get("_row_key").toString()).contains("key25")).collect(Collectors.toList());
    iterator = hfileReader.getIndexedRecordsByKeyPrefixIterator(Collections.singletonList("key25"), avroSchema);
    recordsByPrefix = StreamSupport.stream(Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), false).map(r -> (GenericRecord) r).collect(Collectors.toList());
    assertEquals(expectedKey25, recordsByPrefix);
    // no match. key prefix is beyond entries in file.
    iterator = hfileReader.getIndexedRecordsByKeyPrefixIterator(Collections.singletonList("key99"), avroSchema);
    recordsByPrefix = StreamSupport.stream(Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), false).map(r -> (GenericRecord) r).collect(Collectors.toList());
    assertEquals(Collections.emptyList(), recordsByPrefix);
    // no match. but keyPrefix is in between the entries found in file.
    iterator = hfileReader.getIndexedRecordsByKeyPrefixIterator(Collections.singletonList("key1234"), avroSchema);
    recordsByPrefix = StreamSupport.stream(Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), false).map(r -> (GenericRecord) r).collect(Collectors.toList());
    assertEquals(Collections.emptyList(), recordsByPrefix);
    // filter for "key1", "key30" and "key60" : entries from 'key10 to key19' and 'key30' should be matched.
    List<GenericRecord> expectedKey50and1s = allRecords.stream().filter(entry -> (entry.get("_row_key").toString()).contains("key1") || (entry.get("_row_key").toString()).contains("key30")).collect(Collectors.toList());
    iterator = hfileReader.getIndexedRecordsByKeyPrefixIterator(Arrays.asList("key1", "key30", "key6"), avroSchema);
    recordsByPrefix = StreamSupport.stream(Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), false).map(r -> (GenericRecord) r).collect(Collectors.toList());
    assertEquals(expectedKey50and1s, recordsByPrefix);
    // filter for "key50" and "key0" : entries from key50 and 'key00 to key09' should be matched.
    List<GenericRecord> expectedKey50and0s = allRecords.stream().filter(entry -> (entry.get("_row_key").toString()).contains("key0") || (entry.get("_row_key").toString()).contains("key50")).collect(Collectors.toList());
    iterator = hfileReader.getIndexedRecordsByKeyPrefixIterator(Arrays.asList("key0", "key50"), avroSchema);
    recordsByPrefix = StreamSupport.stream(Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), false).map(r -> (GenericRecord) r).collect(Collectors.toList());
    assertEquals(expectedKey50and0s, recordsByPrefix);
    // filter for "key1" and "key0" : entries from 'key10 to key19' and 'key00 to key09' should be matched.
    List<GenericRecord> expectedKey1sand0s = allRecords.stream().filter(entry -> (entry.get("_row_key").toString()).contains("key1") || (entry.get("_row_key").toString()).contains("key0")).collect(Collectors.toList());
    iterator = hfileReader.getIndexedRecordsByKeyPrefixIterator(Arrays.asList("key0", "key1"), avroSchema);
    recordsByPrefix = StreamSupport.stream(Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), false).map(r -> (GenericRecord) r).collect(Collectors.toList());
    Collections.sort(recordsByPrefix, new Comparator<GenericRecord>() {

        @Override
        public int compare(GenericRecord o1, GenericRecord o2) {
            return o1.get("_row_key").toString().compareTo(o2.get("_row_key").toString());
        }
    });
    assertEquals(expectedKey1sand0s, recordsByPrefix);
    // We expect the keys to be looked up in sorted order. If not, matching entries may not be returned.
    // key1 should have matching entries, but not key0.
    iterator = hfileReader.getIndexedRecordsByKeyPrefixIterator(Arrays.asList("key1", "key0"), avroSchema);
    recordsByPrefix = StreamSupport.stream(Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), false).map(r -> (GenericRecord) r).collect(Collectors.toList());
    Collections.sort(recordsByPrefix, new Comparator<GenericRecord>() {

        @Override
        public int compare(GenericRecord o1, GenericRecord o2) {
            return o1.get("_row_key").toString().compareTo(o2.get("_row_key").toString());
        }
    });
    assertEquals(expectedKey1s, recordsByPrefix);
}

