@Test
public void testFileSystemMetadataPayloadMerging() {
    String partitionName = "2022/10/01";
    Map<String, Long> firstCommitAddedFiles = createImmutableMap(Pair.of("file1.parquet", 1000L), Pair.of("file2.parquet", 2000L), Pair.of("file3.parquet", 3000L));
    HoodieRecord<HoodieMetadataPayload> firstPartitionFilesRecord = HoodieMetadataPayload.createPartitionFilesRecord(partitionName, firstCommitAddedFiles, Collections.emptyList());
    Map<String, Long> secondCommitAddedFiles = createImmutableMap(// NOTE: This is an append
    Pair.of("file3.parquet", 3333L), Pair.of("file4.parquet", 4000L), Pair.of("file5.parquet", 5000L));
    List<String> secondCommitDeletedFiles = Collections.singletonList("file1.parquet");
    HoodieRecord<HoodieMetadataPayload> secondPartitionFilesRecord = HoodieMetadataPayload.createPartitionFilesRecord(partitionName, secondCommitAddedFiles, secondCommitDeletedFiles);
    HoodieMetadataPayload combinedPartitionFilesRecordPayload = secondPartitionFilesRecord.getData().preCombine(firstPartitionFilesRecord.getData());
    HoodieMetadataPayload expectedCombinedPartitionedFilesRecordPayload = HoodieMetadataPayload.createPartitionFilesRecord(partitionName, createImmutableMap(Pair.of("file2.parquet", 2000L), Pair.of("file3.parquet", 3333L), Pair.of("file4.parquet", 4000L), Pair.of("file5.parquet", 5000L)), Collections.emptyList()).getData();
    assertEquals(expectedCombinedPartitionedFilesRecordPayload, combinedPartitionFilesRecordPayload);
}

@Test
public void testColumnStatsPayloadMerging() throws IOException {
    String partitionPath = "2022/10/01";
    String fileName = "file.parquet";
    String targetColName = "c1";
    HoodieColumnRangeMetadata<Comparable> c1Metadata = HoodieColumnRangeMetadata.<Comparable>create(fileName, targetColName, 100, 1000, 5, 1000, 123456, 123456);
    HoodieRecord<HoodieMetadataPayload> columnStatsRecord = HoodieMetadataPayload.createColumnStatsRecords(partitionPath, Collections.singletonList(c1Metadata), false).findFirst().get();
    ////////////////////////////////////////////////////////////////////////
    // Case 1: Combining proper (non-deleted) records
    ////////////////////////////////////////////////////////////////////////
    // NOTE: Column Stats record will only be merged in case existing file will be modified,
    //       which could only happen on storages schemes supporting appends
    HoodieColumnRangeMetadata<Comparable> c1AppendedBlockMetadata = HoodieColumnRangeMetadata.<Comparable>create(fileName, targetColName, 0, 500, 0, 100, 12345, 12345);
    HoodieRecord<HoodieMetadataPayload> updatedColumnStatsRecord = HoodieMetadataPayload.createColumnStatsRecords(partitionPath, Collections.singletonList(c1AppendedBlockMetadata), false).findFirst().get();
    HoodieMetadataPayload combinedMetadataPayload = columnStatsRecord.getData().preCombine(updatedColumnStatsRecord.getData());
    HoodieColumnRangeMetadata<Comparable> expectedColumnRangeMetadata = HoodieColumnRangeMetadata.<Comparable>create(fileName, targetColName, 0, 1000, 5, 1100, 135801, 135801);
    HoodieRecord<HoodieMetadataPayload> expectedColumnStatsRecord = HoodieMetadataPayload.createColumnStatsRecords(partitionPath, Collections.singletonList(expectedColumnRangeMetadata), false).findFirst().get();
    // Assert combined payload
    assertEquals(combinedMetadataPayload, expectedColumnStatsRecord.getData());
    Option<IndexedRecord> alternativelyCombinedMetadataPayloadAvro = columnStatsRecord.getData().combineAndGetUpdateValue(updatedColumnStatsRecord.getData().getInsertValue(null).get(), null);
    // Assert that using legacy API yields the same value
    assertEquals(combinedMetadataPayload.getInsertValue(null), alternativelyCombinedMetadataPayloadAvro);
    ////////////////////////////////////////////////////////////////////////
    // Case 2: Combining w/ deleted records
    ////////////////////////////////////////////////////////////////////////
    HoodieColumnRangeMetadata<Comparable> c1StubbedMetadata = HoodieColumnRangeMetadata.<Comparable>stub(fileName, targetColName);
    HoodieRecord<HoodieMetadataPayload> deletedColumnStatsRecord = HoodieMetadataPayload.createColumnStatsRecords(partitionPath, Collections.singletonList(c1StubbedMetadata), true).findFirst().get();
    // NOTE: In this case, deleted (or tombstone) record will be therefore deleting
    //       previous state of the record
    HoodieMetadataPayload deletedCombinedMetadataPayload = deletedColumnStatsRecord.getData().preCombine(columnStatsRecord.getData());
    assertEquals(deletedColumnStatsRecord.getData(), deletedCombinedMetadataPayload);
    // NOTE: In this case, proper incoming record will be overwriting previously deleted
    //       record
    HoodieMetadataPayload overwrittenCombinedMetadataPayload = columnStatsRecord.getData().preCombine(deletedColumnStatsRecord.getData());
    assertEquals(columnStatsRecord.getData(), overwrittenCombinedMetadataPayload);
}

