@Test
public void testHoodieFlinkClustering() throws Exception {
    // Create hoodie table and insert into data.
    EnvironmentSettings settings = EnvironmentSettings.newInstance().inBatchMode().build();
    TableEnvironment tableEnv = TableEnvironmentImpl.create(settings);
    tableEnv.getConfig().getConfiguration().setInteger(ExecutionConfigOptions.TABLE_EXEC_RESOURCE_DEFAULT_PARALLELISM, 4);
    Map<String, String> options = new HashMap<>();
    options.put(FlinkOptions.PATH.key(), tempFile.getAbsolutePath());
    // use append mode
    options.put(FlinkOptions.OPERATION.key(), WriteOperationType.INSERT.value());
    String hoodieTableDDL = TestConfigurations.getCreateHoodieTableDDL("t1", options);
    tableEnv.executeSql(hoodieTableDDL);
    tableEnv.executeSql(TestSQL.INSERT_T1).await();
    // wait for the asynchronous commit to finish
    TimeUnit.SECONDS.sleep(3);
    // Make configuration and setAvroSchema.
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    FlinkClusteringConfig cfg = new FlinkClusteringConfig();
    cfg.path = tempFile.getAbsolutePath();
    cfg.targetPartitions = 4;
    cfg.sortMemory = 256;
    Configuration conf = FlinkClusteringConfig.toFlinkConfig(cfg);
    assertEquals(256, conf.getInteger(FlinkOptions.WRITE_SORT_MEMORY));
    // create metaClient
    HoodieTableMetaClient metaClient = StreamerUtil.createMetaClient(conf);
    // set the table name
    conf.setString(FlinkOptions.TABLE_NAME, metaClient.getTableConfig().getTableName());
    // set record key field
    conf.setString(FlinkOptions.RECORD_KEY_FIELD, metaClient.getTableConfig().getRecordKeyFieldProp());
    // set partition field
    conf.setString(FlinkOptions.PARTITION_PATH_FIELD, metaClient.getTableConfig().getPartitionFieldProp());
    long ckpTimeout = env.getCheckpointConfig().getCheckpointTimeout();
    conf.setLong(FlinkOptions.WRITE_COMMIT_ACK_TIMEOUT, ckpTimeout);
    conf.setString(FlinkOptions.PARTITION_PATH_FIELD, "partition");
    // set table schema
    CompactionUtil.setAvroSchema(conf, metaClient);
    // judge whether have operation
    // To compute the clustering instant time and do clustering.
    try (HoodieFlinkWriteClient writeClient = FlinkWriteClients.createWriteClient(conf)) {
        HoodieFlinkTable<?> table = writeClient.getHoodieTable();
        String clusteringInstantTime = writeClient.createNewInstantTime();
        boolean scheduled = writeClient.scheduleClusteringAtInstant(clusteringInstantTime, Option.empty());
        assertTrue(scheduled, "The clustering plan should be scheduled");
        // fetch the instant based on the configured execution sequence
        table.getMetaClient().reloadActiveTimeline();
        HoodieTimeline timeline = table.getActiveTimeline().filterPendingReplaceTimeline().filter(instant -> instant.getState() == HoodieInstant.State.REQUESTED);
        // generate clustering plan
        // should support configurable commit metadata
        Option<Pair<HoodieInstant, HoodieClusteringPlan>> clusteringPlanOption = ClusteringUtils.getClusteringPlan(table.getMetaClient(), timeline.lastInstant().get());
        HoodieClusteringPlan clusteringPlan = clusteringPlanOption.get().getRight();
        // Mark instant as clustering inflight
        HoodieInstant instant = HoodieTimeline.getReplaceCommitRequestedInstant(clusteringInstantTime);
        table.getActiveTimeline().transitionReplaceRequestedToInflight(instant, Option.empty());
        final Schema tableAvroSchema = StreamerUtil.getTableAvroSchema(table.getMetaClient(), false);
        final DataType rowDataType = AvroSchemaConverter.convertToDataType(tableAvroSchema);
        final RowType rowType = (RowType) rowDataType.getLogicalType();
        DataStream<ClusteringCommitEvent> dataStream = env.addSource(new ClusteringPlanSourceFunction(clusteringInstantTime, clusteringPlan, conf)).name("clustering_source").uid("uid_clustering_source").rebalance().transform("clustering_task", TypeInformation.of(ClusteringCommitEvent.class), new ClusteringOperator(conf, rowType)).setParallelism(clusteringPlan.getInputGroups().size());
        ExecNodeUtil.setManagedMemoryWeight(dataStream.getTransformation(), conf.getInteger(FlinkOptions.WRITE_SORT_MEMORY) * 1024L * 1024L);
        dataStream.addSink(new ClusteringCommitSink(conf)).name("clustering_commit").uid("uid_clustering_commit").setParallelism(1);
        env.execute("flink_hudi_clustering");
        TestData.checkWrittenData(tempFile, EXPECTED, 4);
    }
}

