@Test
public void testSubtaskFails() throws Exception {
    conf.setLong(FlinkOptions.WRITE_COMMIT_ACK_TIMEOUT, 1L);
    // open the function and ingest data
    preparePipeline().checkpoint(1).assertEmptyEvent().subTaskFails(0).noCompleteInstant().// write a commit and check the result
    consume(TestData.DATA_SET_INSERT).checkpoint(2).assertNextEvent().checkpointComplete(2).checkWrittenData(EXPECTED1).// triggers task 0 failover, there is no pending instant that needs to recommit,
    // the task sends an empty bootstrap event to trigger initialization of a new instant.
    subTaskFails(0, 0).assertEmptyEvent().// rollback the last complete instant to inflight state, to simulate an instant commit failure
    // while executing the post action of a checkpoint success notification event, the whole job should then
    // trigger a failover.
    rollbackLastCompleteInstantToInflight().jobFailover().assertNextEvent().checkLastPendingInstantCompleted().end();
}

@Test
public void testPartialFailover() throws Exception {
    conf.setLong(FlinkOptions.WRITE_COMMIT_ACK_TIMEOUT, 1L);
    conf.setString(FlinkOptions.OPERATION, "INSERT");
    // open the function and ingest data
    preparePipeline().// triggers subtask failure for multiple times to simulate partial failover, for partial over,
    // we allow the task to reuse the pending instant for data flushing, no metadata event should be sent
    subTaskFails(0, 1).assertNoEvent().// the subtask reuses the pending instant
    checkpoint(3).assertNextEvent().// if the write task can not fetch any pending instant when starts up(the coordinator restarts),
    // it will send an event to the coordinator
    coordinatorFails().subTaskFails(0, 2).// the subtask can not fetch the instant to write until a new instant is initialized
    checkpointThrows(4, "Timeout(1000ms) while waiting for instant initialize").assertEmptyEvent().subTaskFails(0, 3).// the last checkpoint instant was rolled back by subTaskFails(0, 2)
    // with EAGER cleaning strategy
    assertNoEvent().end();
}

