@Test
void testSupplementTableConfig() throws Exception {
    String tablePath = new File(tempFile.getAbsolutePath(), "dummy").getAbsolutePath();
    // add pk and pre-combine key to table config
    Configuration tableConf = new Configuration();
    tableConf.setString(FlinkOptions.PATH, tablePath);
    tableConf.setString(FlinkOptions.TABLE_NAME, "t2");
    tableConf.setString(FlinkOptions.RECORD_KEY_FIELD, "f0,f1");
    tableConf.setString(FlinkOptions.PRECOMBINE_FIELD, "f2");
    tableConf.setString(FlinkOptions.TABLE_TYPE, FlinkOptions.TABLE_TYPE_MERGE_ON_READ);
    tableConf.setString(FlinkOptions.PAYLOAD_CLASS_NAME, "my_payload");
    tableConf.setString(FlinkOptions.PARTITION_PATH_FIELD, "partition");
    StreamerUtil.initTableIfNotExists(tableConf);
    Configuration writeConf = new Configuration();
    writeConf.set(FlinkOptions.PATH, tablePath);
    writeConf.set(FlinkOptions.TABLE_NAME, "t2");
    // fallback to table config
    ResolvedSchema schema1 = SchemaBuilder.instance().field("f0", DataTypes.INT().notNull()).field("f1", DataTypes.VARCHAR(20)).field("f2", DataTypes.TIMESTAMP(3)).field("ts", DataTypes.TIMESTAMP(3)).build();
    final MockContext sourceContext1 = MockContext.getInstance(writeConf, schema1, "f2");
    HoodieTableSource source1 = (HoodieTableSource) new HoodieTableFactory().createDynamicTableSource(sourceContext1);
    HoodieTableSink sink1 = (HoodieTableSink) new HoodieTableFactory().createDynamicTableSink(sourceContext1);
    assertThat("pk not provided, fallback to table config", source1.getConf().get(FlinkOptions.RECORD_KEY_FIELD), is("f0,f1"));
    assertThat("pk not provided, fallback to table config", sink1.getConf().get(FlinkOptions.RECORD_KEY_FIELD), is("f0,f1"));
    assertThat("pre-combine key not provided, fallback to table config", source1.getConf().get(FlinkOptions.PRECOMBINE_FIELD), is("f2"));
    assertThat("pre-combine key not provided, fallback to table config", sink1.getConf().get(FlinkOptions.PRECOMBINE_FIELD), is("f2"));
    assertThat("table type not provided, fallback to table config", source1.getConf().get(FlinkOptions.TABLE_TYPE), is(FlinkOptions.TABLE_TYPE_MERGE_ON_READ));
    assertThat("table type not provided, fallback to table config", sink1.getConf().get(FlinkOptions.TABLE_TYPE), is(FlinkOptions.TABLE_TYPE_MERGE_ON_READ));
    assertThat("payload class not provided, fallback to table config", source1.getConf().get(FlinkOptions.PAYLOAD_CLASS_NAME), is("my_payload"));
    assertThat("payload class not provided, fallback to table config", sink1.getConf().get(FlinkOptions.PAYLOAD_CLASS_NAME), is("my_payload"));
    // write config always has higher priority
    // set up a different primary key and pre_combine key with table config options
    writeConf.setString(FlinkOptions.RECORD_KEY_FIELD, "f0");
    writeConf.setString(FlinkOptions.PRECOMBINE_FIELD, "f1");
    final MockContext sourceContext2 = MockContext.getInstance(writeConf, schema1, "f2");
    HoodieTableSource source2 = (HoodieTableSource) new HoodieTableFactory().createDynamicTableSource(sourceContext2);
    HoodieTableSink sink2 = (HoodieTableSink) new HoodieTableFactory().createDynamicTableSink(sourceContext2);
    assertThat("choose pk from write config", source2.getConf().get(FlinkOptions.RECORD_KEY_FIELD), is("f0"));
    assertThat("choose pk from write config", sink2.getConf().get(FlinkOptions.RECORD_KEY_FIELD), is("f0"));
    assertThat("choose preCombine key from write config", source2.getConf().get(FlinkOptions.PRECOMBINE_FIELD), is("f1"));
    assertThat("choose preCombine pk from write config", sink2.getConf().get(FlinkOptions.PRECOMBINE_FIELD), is("f1"));
    writeConf.removeConfig(FlinkOptions.RECORD_KEY_FIELD);
    writeConf.removeConfig(FlinkOptions.PRECOMBINE_FIELD);
    // pk defined in table config but missing in schema will throw
    ResolvedSchema schema2 = SchemaBuilder.instance().field("f1", DataTypes.VARCHAR(20)).field("f2", DataTypes.TIMESTAMP(3)).field("ts", DataTypes.TIMESTAMP(3)).build();
    final MockContext sourceContext3 = MockContext.getInstance(writeConf, schema2, "f2");
    assertDoesNotThrow(() -> new HoodieTableFactory().createDynamicTableSource(sourceContext3), "createDynamicTableSource won't call sanity check");
    assertThrows(HoodieValidationException.class, () -> new HoodieTableFactory().createDynamicTableSink(sourceContext3), "f0 is in table config as record key, but missing in input schema");
}

