@Test
void testFilterPushDownWithParquetPredicates() {
    HoodieTableSource tableSource = getEmptyStreamingSource();
    List<ResolvedExpression> expressions = new ArrayList<>();
    expressions.add(new FieldReferenceExpression("f_int", DataTypes.INT(), 0, 0));
    expressions.add(new ValueLiteralExpression(10));
    ResolvedExpression equalsExpression = new CallExpression(BuiltInFunctionDefinitions.EQUALS, expressions, DataTypes.BOOLEAN());
    CallExpression greaterThanExpression = new CallExpression(BuiltInFunctionDefinitions.GREATER_THAN, expressions, DataTypes.BOOLEAN());
    CallExpression orExpression = new CallExpression(BuiltInFunctionDefinitions.OR, Arrays.asList(equalsExpression, greaterThanExpression), DataTypes.BOOLEAN());
    List<ResolvedExpression> expectedFilters = Arrays.asList(equalsExpression, greaterThanExpression, orExpression);
    tableSource.applyFilters(expectedFilters);
    String actualPredicates = tableSource.getPredicates().toString();
    assertEquals(ExpressionPredicates.fromExpression(expectedFilters).toString(), actualPredicates);
}

@Test
void getValueFromLiteralForNull() {
    List<RowType.RowField> fields = ((RowType) ROW_DATA_TYPE.getLogicalType()).getFields();
    List<DataType> dataTypes = ROW_DATA_TYPE.getChildren();
    CallExpression callExpression;
    for (int i = 0; i < fields.size(); i++) {
        // 1. Build all types
        callExpression = new CallExpression(BuiltInFunctionDefinitions.IS_NOT_NULL, Arrays.asList(new FieldReferenceExpression(fields.get(i).getName(), dataTypes.get(i), 2, 2), new ValueLiteralExpression(null, dataTypes.get(i))), DataTypes.BOOLEAN());
        List<Expression> childExprs = callExpression.getChildren();
        // 2. Parse each type
        boolean hasNullLiteral = childExprs.stream().anyMatch(e -> e instanceof ValueLiteralExpression && ExpressionUtils.getValueFromLiteral((ValueLiteralExpression) e) == null);
        assertTrue(hasNullLiteral);
    }
}

@Test
void getValueFromLiteralForNonNull() {
    List<RowType.RowField> fields = ((RowType) ROW_DATA_TYPE_FIELD_NON_NULL.getLogicalType()).getFields();
    List<DataType> dataTypes = ROW_DATA_TYPE_FIELD_NON_NULL.getChildren();
    // tests for non-null literals
    List<Object> dataList = new ArrayList<>(fields.size());
    // f_tinyint
    dataList.add(new Byte("1"));
    // f_smallint
    dataList.add(new Short("2"));
    // f_int
    dataList.add(new Integer("3"));
    // f_long
    dataList.add(new Long("4"));
    // f_float
    dataList.add(new Float(5.0));
    // f_double
    dataList.add(new Double(6.0));
    // f_boolean
    dataList.add(new Boolean(true));
    // f_decimal
    dataList.add(new BigDecimal(3.0));
    // f_bytes
    dataList.add(getUTF8Bytes("hudi"));
    // f_string
    dataList.add("hudi ok");
    // f_time
    dataList.add(LocalTime.of(1, 11, 11));
    // f_date
    dataList.add(LocalDate.of(2023, 1, 2));
    // f_timestamp
    dataList.add(LocalDateTime.of(2023, 1, 2, 3, 4));
    CallExpression callExpression;
    for (int i = 0; i < fields.size(); i++) {
        // 1. Build all types
        callExpression = new CallExpression(BuiltInFunctionDefinitions.IS_NOT_NULL, Arrays.asList(new FieldReferenceExpression(fields.get(i).getName(), dataTypes.get(i), i, i), new ValueLiteralExpression(dataList.get(i), dataTypes.get(i))), DataTypes.BOOLEAN());
        List<Expression> childExprs = callExpression.getChildren();
        // 2. Parse each type
        if (dataList.get(i) instanceof LocalTime) {
            assertEquals(((LocalTime) dataList.get(i)).get(ChronoField.MILLI_OF_DAY), ExpressionUtils.getValueFromLiteral((ValueLiteralExpression) childExprs.get(1)));
        } else if (dataList.get(i) instanceof LocalDate) {
            assertEquals(((LocalDate) dataList.get(i)).toEpochDay(), ExpressionUtils.getValueFromLiteral((ValueLiteralExpression) childExprs.get(1)));
        } else if (dataList.get(i) instanceof LocalDateTime) {
            assertEquals(((LocalDateTime) dataList.get(i)).toInstant(ZoneOffset.UTC).toEpochMilli(), ExpressionUtils.getValueFromLiteral((ValueLiteralExpression) childExprs.get(1)));
        } else {
            assertEquals(dataList.get(i), ExpressionUtils.getValueFromLiteral((ValueLiteralExpression) childExprs.get(1)));
        }
    }
}

