/**
 * 1. If there is any ongoing writing, cannot schedule clustering
 * 2. If the clustering is scheduled, it cannot block incoming new writers
 */
@ParameterizedTest
@ValueSource(booleans = { true, false })
public void testConcurrentWrite(boolean rowWriterEnable) throws IOException {
    setup(5120);
    config.setValue("hoodie.datasource.write.row.writer.enable", String.valueOf(rowWriterEnable));
    String writeTime = writeClient.createNewInstantTime();
    List<WriteStatus> writeStatues = writeData(writeTime, 2000, false);
    // Cannot schedule clustering if there is in-flight writer
    Assertions.assertFalse(writeClient.scheduleClustering(Option.empty()).isPresent());
    Assertions.assertTrue(writeClient.commitStats(writeTime, context.parallelize(writeStatues, 1), writeStatues.stream().map(WriteStatus::getStat).collect(Collectors.toList()), Option.empty(), metaClient.getCommitActionType()));
    metaClient = HoodieTableMetaClient.reload(metaClient);
    // Schedule clustering
    String clusteringTime = (String) writeClient.scheduleClustering(Option.empty()).get();
    // Concurrent is not blocked by the clustering
    writeData(writeClient.createNewInstantTime(), 2000, true);
    // The records are immediately visible when the writer completes
    Assertions.assertEquals(4000, readRecords().size());
    // Clustering finished, check the number of records (there will be file group switch in the background)
    writeClient.cluster(clusteringTime, true);
    Assertions.assertEquals(4000, readRecords().size());
}

@Test
public void testInertsWithEmptyCommitsHavingWriterSchemaAsNull() throws Exception {
    HoodieWriteConfig.Builder cfgBuilder = getConfigBuilder().withAutoCommit(false);
    addConfigsForPopulateMetaFields(cfgBuilder, false);
    // Re-init meta client with write config props.
    metaClient = HoodieTestUtils.init(basePath, HoodieTableType.MERGE_ON_READ, cfgBuilder.build().getProps());
    SparkRDDWriteClient client = getHoodieWriteClient(cfgBuilder.build());
    try {
        String firstCommit = "001";
        int numRecords = 200;
        JavaRDD<WriteStatus> result = insertFirstBatch(cfgBuilder.build(), client, firstCommit, "000", numRecords, SparkRDDWriteClient::insert, false, false, numRecords);
        assertTrue(client.commit(firstCommit, result), "Commit should succeed");
        // Re-init client with null writer schema.
        cfgBuilder = getConfigBuilder((String) null).withAutoCommit(false);
        addConfigsForPopulateMetaFields(cfgBuilder, false);
        client = getHoodieWriteClient(cfgBuilder.build());
        String secondCommit = "002";
        client.startCommitWithTime(secondCommit);
        JavaRDD<HoodieRecord> emptyRdd = context.emptyRDD();
        result = client.insert(emptyRdd, secondCommit);
        assertTrue(client.commit(secondCommit, result), "Commit should succeed");
        // Schema Validations.
        HoodieTableMetaClient metaClient = HoodieTableMetaClient.builder().setConf(jsc.hadoopConfiguration()).setBasePath(basePath).build();
        HoodieActiveTimeline timeline = metaClient.getActiveTimeline();
        HoodieCommitMetadata metadata = HoodieCommitMetadata.fromBytes(timeline.getInstantDetails(timeline.lastInstant().get()).get(), HoodieCommitMetadata.class);
        assertTrue(metadata.getExtraMetadata().get("schema").isEmpty());
        TableSchemaResolver tableSchemaResolver = new TableSchemaResolver(metaClient);
        assertEquals(Schema.parse(TRIP_EXAMPLE_SCHEMA), tableSchemaResolver.getTableAvroSchema(false));
        // Data Validations.
        Dataset<Row> df = sparkSession.read().format("hudi").load(basePath);
        assertEquals(numRecords, df.collectAsList().size());
    } finally {
        client.close();
    }
}

@ParameterizedTest
@MethodSource("configParams")
public void testKeyGeneratorTypes(String keyGenType) throws IOException {
    props.put(HoodieWriteConfig.KEYGENERATOR_TYPE.key(), keyGenType);
    KeyGeneratorType keyType = KeyGeneratorType.valueOf(keyGenType);
    if (keyType == KeyGeneratorType.CUSTOM) {
        // input needs to be properly formatted
        props.put(KeyGeneratorOptions.PARTITIONPATH_FIELD_NAME.key(), "timestamp:timestamp");
    }
    KeyGenerator keyGenerator = HoodieSparkKeyGeneratorFactory.createKeyGenerator(props);
    switch(keyType) {
