@Test
public void testReentrantLock() throws Exception {
    HiveMetastoreBasedLockProvider lockProvider = new HiveMetastoreBasedLockProvider(lockConfiguration, hiveConf());
    lockComponent.setOperationType(DataOperationType.NO_TXN);
    Assertions.assertTrue(lockProvider.acquireLock(lockConfiguration.getConfig().getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS, lockComponent));
    try {
        lockProvider.acquireLock(lockConfiguration.getConfig().getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS, lockComponent);
        Assertions.fail();
    } catch (IllegalArgumentException e) {
        // expected
    }
    lockProvider.unlock();
    // not acquired in the beginning
    HiveMetastoreBasedLockProvider lockProvider1 = new HiveMetastoreBasedLockProvider(lockConfiguration, hiveConf());
    HiveMetastoreBasedLockProvider lockProvider2 = new HiveMetastoreBasedLockProvider(lockConfiguration, hiveConf());
    lockComponent.setOperationType(DataOperationType.NO_TXN);
    Assertions.assertTrue(lockProvider1.acquireLock(lockConfiguration.getConfig().getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS, lockComponent));
    try {
        boolean acquireStatus = lockProvider2.acquireLock(lockConfiguration.getConfig().getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS, lockComponent);
        Assertions.assertFalse(acquireStatus);
    } catch (IllegalArgumentException e) {
        // expected
    }
    lockProvider1.unlock();
    Assertions.assertTrue(lockProvider2.acquireLock(lockConfiguration.getConfig().getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS, lockComponent));
    lockProvider2.unlock();
    lockProvider.close();
    lockProvider1.close();
    lockProvider2.close();
}

@Test
public void testWaitingLock() throws Exception {
    // create different HiveMetastoreBasedLockProvider to simulate different applications
    HiveMetastoreBasedLockProvider lockProvider1 = new HiveMetastoreBasedLockProvider(lockConfiguration, hiveConf());
    HiveMetastoreBasedLockProvider lockProvider2 = new HiveMetastoreBasedLockProvider(lockConfiguration, hiveConf());
    lockComponent.setOperationType(DataOperationType.NO_TXN);
    Assertions.assertTrue(lockProvider1.acquireLock(lockConfiguration.getConfig().getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS, lockComponent));
    try {
        boolean acquireStatus = lockProvider2.acquireLock(lockConfiguration.getConfig().getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS, lockComponent);
        Assertions.assertFalse(acquireStatus);
    } catch (IllegalArgumentException e) {
        // expected
    }
    lockProvider1.unlock();
    // create the third HiveMetastoreBasedLockProvider to acquire lock
    HiveMetastoreBasedLockProvider lockProvider3 = new HiveMetastoreBasedLockProvider(lockConfiguration, hiveConf());
    boolean acquireStatus = lockProvider3.acquireLock(lockConfiguration.getConfig().getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS, lockComponent);
    // we should acquired lock, since lockProvider1 has already released lock
    Assertions.assertTrue(acquireStatus);
    lockProvider3.unlock();
    // close all HiveMetastoreBasedLockProvider
    lockProvider1.close();
    lockProvider2.close();
    lockProvider3.close();
}

