@Test
void testMetaSyncConcurrency() throws Exception {
    String syncToolClassName = DummySyncTool1.class.getName();
    String baseFileFormat = "PARQUET";
    String tableName1 = "table1";
    String tableName2 = "table2";
    String targetBasePath1 = "path/to/target1";
    String targetBasePath2 = "path/to/target2";
    TypedProperties props1 = new TypedProperties();
    props1.setProperty(META_SYNC_TABLE_NAME.key(), tableName1);
    TypedProperties props2 = new TypedProperties();
    props1.setProperty(META_SYNC_TABLE_NAME.key(), tableName2);
    // Simulate processing time here
    HoodieSyncTool syncToolMock = mock(HoodieSyncTool.class);
    doAnswer(invocation -> {
        Thread.sleep(1000);
        return null;
    }).when(syncToolMock).syncHoodieTable();
    AtomicBoolean targetBasePath1Running = new AtomicBoolean(false);
    AtomicBoolean targetBasePath2Running = new AtomicBoolean(false);
    ExecutorService executor = Executors.newFixedThreadPool(4);
    // Submitting tasks with targetBasePath1
    executor.submit(() -> {
        targetBasePath1Running.set(true);
        SyncUtilHelpers.runHoodieMetaSync(syncToolClassName, props1, hadoopConf, fileSystem, targetBasePath1, baseFileFormat);
        targetBasePath1Running.set(false);
    });
    executor.submit(() -> {
        // Only one lock should exist for this base path
        assertEquals(1, SyncUtilHelpers.getNumberOfLocks());
        SyncUtilHelpers.runHoodieMetaSync(syncToolClassName, props1, hadoopConf, fileSystem, targetBasePath1, baseFileFormat);
    });
    // Submitting tasks with targetBasePath2
    executor.submit(() -> {
        targetBasePath2Running.set(true);
        SyncUtilHelpers.runHoodieMetaSync(syncToolClassName, props2, hadoopConf, fileSystem, targetBasePath2, baseFileFormat);
        targetBasePath2Running.set(false);
    });
    executor.submit(() -> {
        // Two locks should exist for both base paths
        assertEquals(2, SyncUtilHelpers.getNumberOfLocks());
        SyncUtilHelpers.runHoodieMetaSync(syncToolClassName, props2, hadoopConf, fileSystem, targetBasePath2, baseFileFormat);
    });
    executor.shutdown();
    assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
    // Check if there was a time when both paths were running in parallel
    assertTrue(targetBasePath1Running.get() && targetBasePath2Running.get(), "The methods did not run concurrently for different base paths");
}

@Test
public void testRemoteHoodieTableFileSystemViewWithRetry() {
    // Service is available.
    view.getLatestBaseFiles();
    // Shut down the service.
    server.close();
    try {
        // Immediately fails and throws a connection refused exception.
        view.getLatestBaseFiles();
        fail("Should be catch Exception 'Connection refused (Connection refused)'");
    } catch (HoodieRemoteException e) {
        assert e.getMessage().contains("Connection refused (Connection refused)");
    }
    // Enable API request retry for remote file system view.
    view = new RemoteHoodieTableFileSystemView(metaClient, FileSystemViewStorageConfig.newBuilder().withRemoteServerHost("localhost").withRemoteServerPort(server.getServerPort()).withRemoteTimelineClientRetry(true).withRemoteTimelineClientMaxRetryIntervalMs(2000L).withRemoteTimelineClientMaxRetryNumbers(4).build());
    try {
        view.getLatestBaseFiles();
        fail("Should be catch Exception 'Connection refused (Connection refused)'");
    } catch (HoodieRemoteException e) {
        assert e.getMessage().contains("Connection refused (Connection refused)");
    }
    // Retry succeed after 2 or 3 tries.
    new Thread(() -> {
        try {
            Thread.sleep(5000L);
            LOG.info("Restart server.");
            server.startService();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }).run();
    view.getLatestBaseFiles();
    server.close();
}

