    new File(topicPath + "/year=2016/month=05/day=01/" + "topic1+0+100+200" + BASE_FILE_EXTENSION).createNewFile();
    new File(topicPath + "/year=2016/month=05/day=01/" + "topic1+1+100+200" + BASE_FILE_EXTENSION).createNewFile();
